import builtins, time
from nuka.editor.app import ActionError
def fails(action, text, **args):
    try:
        app.actions.run(action, **args)
    except ActionError as e:
        assert text in str(e), (action, args, str(e))
    else:
        raise AssertionError((action, args))
def settle():
    deadline = time.monotonic() + 30.0
    while app.actions.run('ui.pointer_status')['busy']:
        assert time.monotonic() < deadline, app.actions.run('ui.pointer_status')
        app.update(True)
    for _ in range(3):
        app.update(True)
    return app.actions.run('ui.pointer_status')
def point(**args):
    app.actions.run('ui.pointer', **args)
    return settle()
def checked(action):
    return next(a for a in app.actions.list() if a['id'] == action)['checked']
for k, v in dict(fails=fails, settle=settle, point=point, checked=checked).items():
    setattr(builtins, 'pt_' + k, v)
r = app.actions.run('view.record_status')
assert r['on'] is False and r['frames'] == 0, r
fails('view.record', 'the codec is nvenc or x264', on=True, codec='h265')
fails('view.record', 'fps: 1 to 120', on=True, fps=0)
fails('view.record', 'the window is not being recorded', on=False)
fails('ui.pointer', 'the button is left, middle or right', to=[10, 10], button='side')
fails('view.project', 'point: [x, y, z]')
p = app.actions.run('ui.pointer_status')
assert p['on'] is False and p['busy'] is False and p['error'] is None, p
